    /**
     * Tests getting all DataBreachs.
     *
     * @return    Collection
     */
    public List<DataBreach> testGetAll() throws Throwable {
    LOGGER.info( "DataBreachTest:testGetAll() - Retrieving Collection of DataBreachs:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all DataBreach : " );
    List<DataBreach> collection  = null;

    try {
        // call the static get method on the DataBreachService
        collection = service.getAllDataBreach();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            DataBreach currEntity  = null;
            Iterator<DataBreach> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getDataBreachId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

